(() => {
  'use strict';
  const C=window.GBCore,U=window.GB_SESSION,TEAM=window.GB_TEAM||[],el=id=>document.getElementById(id);
  let saved='en';try{saved=localStorage.getItem('gbtor365-language')||'en';}catch{}
  const state={lang:saved==='es'?'es':'en',view:'overview',workspace:{batches:{items:[],total:0},mappings:{items:[]},events:[]},batch:null,query:'',tab:'invoices',page:0,busy:false};
  const t=(en,es)=>state.lang==='es'?es:en;
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const money=n=>new Intl.NumberFormat(state.lang==='es'?'es-MX':'en-US',{style:'currency',currency:'USD'}).format((n||0)/100);
  const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',invoice:'M6 3h12v18l-3-2-3 2-3-2-3 2V3z M9 7h6 M9 11h6 M9 15h3',chart:'M4 3v17h17 M8 15v-4 M13 15V7 M18 15V4',mapping:'M3 6h7 M14 6h7 M3 18h7 M14 18h7 M10 3v6 M14 15v6 M10 6l4 12',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M22 21v-2a4 4 0 0 0-3-3.87 M16 3.13a4 4 0 0 1 0 7.75 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',book:'M12 5v16 M12 5C8 2 4 3 2 4v16c4-1 7-1 10 1 3-2 6-2 10-1V4c-4-1-7-2-10 1',arrow:'M4 12h16 M15 7l5 5-5 5',external:'M14 3h7v7 M10 14L21 3 M21 14v6a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V4a1 1 0 0 1 1-1h6',plus:'M12 5v14 M5 12h14',chevron:'M9 5l7 7-7 7',down:'M6 9l6 6 6-6',check:'M5 12l4 4L19 6',shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3z M8 12l3 3 5-6',alert:'M12 3L2 21h20L12 3z M12 9v5 M12 17v.5',file:'M14 2H5a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V9l-7-7z M14 2v7h7 M7 13h10 M7 17h7',upload:'M12 16V3 M7 8l5-5 5 5 M4 15v5a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-5',download:'M12 3v13 M7 11l5 5 5-5 M4 16v5h16v-5',search:'M21 21l-6-6 M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',sync:'M4 7h14l-4-4 M20 17H6l4 4 M18 7l-4 4 M6 17l4-4',calendar:'M3 5h18v16H3z M3 10h18 M7 3v4 M17 3v4',menu:'M3 6h18 M3 12h18 M3 18h18',close:'M6 6l12 12 M6 18L18 6',info:'M12 11v6 M12 7v.1 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',reset:'M3 10V4 M3 10h6 M3 10a9 9 0 1 1 1 8',edit:'M14 4l6 6 M4 20l4-1L21 6l-3-3L5 16l-1 4z',folder:'M3 5h6l2 3h10v12H3V5z',lock:'M5 10h14v11H5z M8 10V6a4 4 0 0 1 8 0v4',link:'M10 14l4-4 M8 16l-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0 M16 8l2-2a4 4 0 0 0-6-6L7 5'};
  const icon=(name,size=17)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;
  const labels={overview:()=>t('Overview','Resumen'),ap:()=>t('Supplier invoices','Facturas de proveedores'),sales:()=>t('Sales journals','Pólizas de ventas'),mapping:()=>t('Report types & mappings','Tipos de reporte y correspondencias'),activity:()=>t('Activity log','Historial'),team:()=>t('Team & access','Equipo y accesos'),guide:()=>t('Workflow guide','Guía de procesos'),r365:()=>t('R365 TEST connection','Conexión R365 TEST')};
  const role=r=>({admin:t('Administrator','Administrador'),reviewer:t('Review & export','Revisión y exportación'),preparer:t('Preparation','Preparación'),finance:t('Finance oversight','Supervisión financiera'),viewer:t('Read only','Solo consulta')}[r]||r);
  const status=s=>({blocked:t('Blocked','Bloqueado'),checked:t('Checks completed','Controles completados'),needs_review:t('Review required','Requiere revisión'),validated:t('Validated','Validado'),approved:t('Approved','Aprobado'),exported:t('CSV generated','CSV generado')}[s]||s);
  const issueName=code=>({negative:t('Negative entries — confirm treatment','Asientos negativos — confirmar tratamiento'),period:t('Comment refers to a different period','Comentario de otro período'),locations:t('Multiple accounting locations','Varias ubicaciones contables'),duplicate_document:t('Document also found in another batch','Documento presente en otro lote'),source_column:t('Required source column missing','Falta columna de origen'),period_range:t('Date is outside the selected period','Fecha fuera del período seleccionado'),mismatch:t('Invoice total differs from its allocations','Total de factura distinto al detalle'),unbalanced:t('Journal is not balanced','Póliza no balanceada'),transform:t('Transformation or code mapping failed','Falló la transformación o correspondencia'),group_conflict:t('Grouping would discard different source values','Agrupar descartaría valores diferentes'),empty:t('No rows remain after filtering','No quedan filas tras filtrar')}[code]||code);
  const errorText=code=>({forbidden:t('Your account cannot perform this action.','Tu cuenta no puede realizar esta acción.'),storage_unavailable:t('Persistent storage is unavailable. No completed action has been confirmed. Please retry.','El almacenamiento no está disponible. No se ha confirmado la acción. Inténtalo de nuevo.'),conflict:t('This record changed. Refresh it before retrying.','Este registro cambió. Actualízalo antes de reintentar.'),file_format:t('Choose a UTF-8 CSV file.','Elige un archivo CSV UTF-8.'),encoding:t('The source file must use UTF-8 encoding.','El archivo debe estar codificado en UTF-8.'),file_limit:t('Maximum: 2 MB, 20,000 rows and 100 columns.','Máximo: 2 MB, 20.000 filas y 100 columnas.'),converted_limit:t('The transformed file exceeds the supported size. Split the source report.','El archivo transformado excede el tamaño admitido. Divide el reporte.'),period:t('Select a valid start and end date.','Selecciona fechas de inicio y fin válidas.'),review_required:t('Complete validation and document every required review checkpoint.','Completa la validación y documenta todos los puntos de revisión.'),validation_errors:t('Resolve the blocking controls before approval.','Resuelve los controles bloqueantes antes de aprobar.'),approval_required:t('This batch must be approved before export.','El lote debe estar aprobado antes de exportar.'),mapping_validation:t('The mapping does not pass the source-file controls. Review the field associations and formats.','La correspondencia no supera los controles. Revisa campos y formatos.'),r365_not_configured:t('R365 TEST access and the documented write API are required. Nothing was sent.','Se requieren acceso a R365 TEST y la API de escritura documentada. No se envió nada.')}[code]||t('Unable to complete this action: ','No se pudo completar esta acción: ')+code);
  const avatar=u=>`<span class="avatar">${esc(u?.initials||'')}</span>`;
  const pill=(value,kind='')=>`<span class="pill ${kind}">${value}</span>`;
  const btn=(label,action,kind='',ico='',attrs='')=>`<button class="btn ${kind}" data-action="${action}" ${attrs}>${ico?icon(ico,15):''}${label}</button>`;
  const batches=kind=>state.workspace.batches.items.filter(b=>!kind||b.kind===kind);
  const period=b=>b?.period?esc(b.period.from+' → '+b.period.to):'—';
  const head=(title,description,action='')=>`<div class="page-head"><div><div class="eyebrow">ARTIMEX / ${t('FINANCE WORKSPACE','ESPACIO CONTABLE')}</div><h1>${title}</h1><p>${description}</p></div>${action}</div>`;
  function toast(text){el('toast').textContent=text;el('toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el('toast').classList.remove('visible'),5000);}
  async function api(path,body){
    const response=await fetch('/api/'+path,{method:body===undefined?'GET':'POST',credentials:'same-origin',cache:'no-store',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});
    if(response.status===401){location.replace('/login');throw Error(t('Session expired','Sesión vencida'));}
    if(!response.ok){let data={};try{data=await response.json();}catch{}throw Error(errorText(data.error||String(response.status))+(typeof data.detail==='string'?' '+data.detail:''));}
    return response;
  }
  async function json(path,body){return (await api(path,body)).json();}
  async function refresh(){state.workspace=await json('workspace');}
  async function selectBatch(id){state.batch=await json('batches/'+id);state.tab='invoices';state.query='';state.page=0;render();}
  async function nav(view){state.view=view;state.query='';state.page=0;history.replaceState(null,'','#'+view);
    if(['ap','sales'].includes(view)&&state.batch?.kind!==view){const first=batches(view)[0];state.batch=first?await json('batches/'+first.id):null;}
    render();window.scrollTo({top:0,behavior:'instant'});
  }
  function render(){
    document.documentElement.lang=state.lang;
    const counts=batches().filter(b=>['blocked','needs_review'].includes(b.status)).length;
    el('app').innerHTML=`<div class="shell"><div class="mobile-scrim" data-action="menu"></div><aside class="sidebar"><a class="brand" href="#overview" data-nav="overview" aria-label="Artimex overview"><img src="assets/artimex-logo.webp" alt="Artimex Artisan Mexican Bakery"></a><div class="side-product"><span class="product-mark">${icon('sync',22)}</span><div><strong>GBtoR365</strong><small>${t('FINANCE CONNECTION','CONEXIÓN CONTABLE')}</small></div></div><nav class="nav-group"><div class="nav-caption">${t('WORKSPACE','ESPACIO DE TRABAJO')}</div>${['overview','ap','sales','mapping','activity','r365'].map((v,i)=>`<button class="nav-item ${state.view===v?'active':''}" data-nav="${v}" ${state.view===v?'aria-current="page"':''}>${icon(['grid','invoice','chart','mapping','clock','link'][i])}${labels[v]()}${v==='overview'&&counts?`<span class="nav-count">${counts}</span>`:''}</button>`).join('')}</nav><nav class="nav-group"><div class="nav-caption">${t('MANAGEMENT','ADMINISTRACIÓN')}</div>${['team','guide'].map((v,i)=>`<button class="nav-item ${state.view===v?'active':''}" data-nav="${v}" ${state.view===v?'aria-current="page"':''}>${icon(i?'book':'users')}${labels[v]()}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-note"><div class="eyebrow">ARTIMEX CONNECT</div><small>${t('GlobalBake → Restaurant365<br>Manual source reports, tracked processing.','GlobalBake → Restaurant365<br>Reportes manuales, proceso trazable.')}</small><a href="https://orderstogb.artimexbakery.com/" target="_blank" rel="noopener">EGG Order ${icon('external',13)}</a></div><div class="version"><span>GBtoR365 · v0.2</span><span>${t('Workspace','Portal')}</span></div></div></aside><div class="main-shell"><header class="topbar"><button class="icon-btn mobile-menu" data-action="menu" aria-label="${t('Open menu','Abrir menú')}">${icon('menu')}</button><div class="breadcrumb"><span class="crumb-parent">Artimex</span><span class="crumb-slash">/</span><strong>${labels[state.view]()}</strong></div><div class="top-tools"><span class="mode-badge">${t('ACCOUNTING WORKSPACE','ESPACIO CONTABLE')}</span><button class="language" data-action="language">${state.lang==='en'?'EN':'ES'} ${icon('down',11)}</button><span class="top-divider"></span><button class="user-button" data-action="profile" aria-label="${t('Account menu','Menú de cuenta')}">${avatar(U)}<span><strong>${esc(U.name)}</strong><small>${role(U.role)}</small></span>${icon('down',12)}</button></div></header><main class="content" id="main"><div class="screen-enter">${({overview,ap:workspace,sales:workspace,mapping,activity,team,guide,r365}[state.view])()}</div><footer class="footer"><span>${icon('lock',11)}${t('Source files, checks and decisions are stored on the server.','Archivos originales, controles y decisiones conservados en el servidor.')}</span><span>${t('R365 TEST API not configured','API R365 TEST sin configurar')}</span></footer></main></div></div>`;
  }
  function stat(title,value,note,ico){return `<div class="stat"><div class="stat-top"><span>${title}</span><span class="stat-icon">${icon(ico,14)}</span></div><strong>${value}</strong><small>${note}</small></div>`;}
  function empty(title,description,action=''){return `<div class="empty">${icon('folder',32)}<h3>${title}</h3><p>${description}</p>${action?`<div class="empty-action">${action}</div>`:''}</div>`;}
  function overview(){const all=batches();return `${head(t('Your accounting, in sync.','Tu contabilidad, conectada.'),t('Upload the report, apply the saved mapping, review the controls and prepare the R365 file.','Carga el reporte, aplica la correspondencia guardada, revisa los controles y prepara el archivo R365.'),btn(t('Upload a CSV report','Cargar un reporte CSV'),'import','primary','upload',U.permissions.prepare?'':'disabled'))}<section class="hero-panel"><div class="hero-copy"><div class="eyebrow">${t('FROM OPERATIONS TO ACCOUNTING','DE LA OPERACIÓN A LA CONTABILIDAD')}</div><h2>${t('Your source files.<br>A traceable accounting process.','Tus archivos originales.<br>Un proceso contable trazable.')}</h2><p>${t('Rosa or Jorge exports the report from GlobalBake, then uploads the CSV here. Every processing step is retained.','Rosa o Jorge genera el reporte en GlobalBake y carga aquí el CSV. Cada etapa queda registrada.')}</p></div><div class="hero-route"><div class="route-node"><b>GlobalBake</b><small>${t('MANUAL CSV','CSV MANUAL')}</small></div><div class="route-line"></div><div class="route-center">${icon('sync',20)}</div><div class="route-line"></div><div class="route-node r365"><b>R365 TEST</b><small>${t('CONNECTION PENDING','CONEXIÓN PENDIENTE')}</small></div></div></section><section class="stats">${stat(t('Uploaded files','Archivos cargados'),state.workspace.batches.total,t('Originals retained','Originales conservados'),'file')}${stat(t('To review or resolve','Por revisar o resolver'),all.filter(b=>['blocked','needs_review'].includes(b.status)).length,t('In the listed batches','En los lotes listados'),'alert')}${stat(t('Approved batches','Lotes aprobados'),all.filter(b=>b.approved).length,t('Nominative decisions','Decisiones nominativas'),'shield')}${stat(t('Confirmed R365 imports','Imports R365 confirmados'),0,t('Test API access required','Se requiere acceso a API de prueba'),'link')}</section><div class="workflow-grid">${['ap','sales'].map(kind=>`<section class="workflow-card ${kind==='sales'?'sales':''}"><div class="workflow-heading"><span class="workflow-icon">${icon(kind==='ap'?'invoice':'chart',22)}</span>${pill(kind==='ap'?'AP':'JE')}</div><h3>${labels[kind]()}</h3><p>${t('Uploaded files and server controls, with their original period and mapping version.','Archivos cargados y controles del servidor, con su período y versión de correspondencia.')}</p><div class="workflow-meta"><span>${batches(kind).length} ${t('batches','lotes')}</span></div><div class="workflow-footer"><span></span><button class="btn small" data-nav="${kind}">${t('Open workflow','Abrir proceso')} ${icon('arrow',14)}</button></div></section>`).join('')}</div><section class="panel"><div class="panel-heading"><h2>${t('Recent batches','Lotes recientes')}</h2>${btn(t('Refresh','Actualizar'),'refresh','small','sync')}</div>${batchTable(all)}</section>${r365Notice()}`;}
  function batchTable(list){return list.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>${t('Source file','Archivo original')}</th><th>${t('Period','Período')}</th><th>${t('Uploaded by','Cargado por')}</th><th>${t('Status','Estado')}</th><th></th></tr></thead><tbody>${list.map(b=>`<tr><td class="row-title">${esc(b.name)}<small>${b.kind.toUpperCase()} · ${b.rows} ${t('transformed rows','filas transformadas')}</small></td><td>${period(b)}</td><td>${esc(b.createdBy)}</td><td>${pill(status(b.status),b.status==='blocked'?'red':b.status==='needs_review'?'amber':'')}</td><td><button class="icon-btn" data-action="open-batch" data-id="${b.id}" data-kind="${b.kind}" aria-label="${t('Open batch','Abrir lote')}">${icon('chevron',14)}</button></td></tr>`).join('')}</tbody></table></div>${state.workspace.batches.total>state.workspace.batches.items.length?`<p class="small-note">${t('Showing the latest 500 batches.','Se muestran los últimos 500 lotes.')}</p>`:''}`:empty(t('No file uploaded yet','Todavía no se ha cargado ningún archivo'),t('This workspace starts empty. Upload a source CSV to begin.','Este espacio comienza vacío. Carga un CSV original para empezar.'));}
  function workspace(){const kind=state.view,b=state.batch?.kind===kind?state.batch:null,list=batches(kind);return `${head(labels[kind](),t('Manual CSV upload → saved mapping → server checks → review → approved export','Carga manual de CSV → correspondencia guardada → controles → revisión → exportación aprobada'),btn(t('Upload a CSV report','Cargar un reporte CSV'),'import','primary','upload',`data-kind="${kind}" ${U.permissions.prepare?'':'disabled'}`))}${!b?`<section class="panel">${empty(t('No source report has been uploaded','No se ha cargado ningún reporte original'),t('Select the report exported from GlobalBake. No invoices are created or preloaded by the portal.','Selecciona el reporte exportado de GlobalBake. El portal no crea ni precarga facturas.'),btn(t('Upload the first CSV','Cargar el primer CSV'),'import','primary','upload',`data-kind="${kind}" ${U.permissions.prepare?'':'disabled'}`))}</section>`:`<div class="batch-picker"><label>${t('Batch','Lote')}<select class="select" id="batch-select" aria-label="${t('Select batch','Seleccionar lote')}">${list.map(item=>`<option value="${item.id}" ${item.id===b.id?'selected':''}>${esc(item.name)} · ${esc(item.period.from)} · ${status(item.status)}</option>`).join('')}</select></label>${pill(status(b.status),b.status==='blocked'?'red':'')}</div><div class="workflow-steps">${[t('Upload','Cargar'),t('Check','Controlar'),t('Review','Revisar'),t('Export','Exportar')].map((s,i)=>`<div class="step ${i===0||i===1&&b.validated||i===2&&b.approval||i===3&&b.status==='exported'?'active':''}"><i>${i+1}</i>${s}</div>`).join('')}</div><div class="workspace-grid"><section class="panel"><div class="file-bar"><div class="file-info"><span class="file-icon">${icon('file',20)}</span><div><strong>${esc(b.name)}</strong><small>${esc(b.createdBy)} · ${period(b)}<br>${b.sourceRows} ${t('source rows','filas originales')} · ${b.rows.length} ${t('transformed rows','filas transformadas')} · ${b.excluded} ${t('excluded by mapping filter','excluidas por filtro')}</small></div></div><a class="btn small" href="/api/batches/${b.id}/original">${icon('download',14)}${t('Original CSV','CSV original')}</a></div><div class="tabs">${['invoices','lines','target'].map((tab,i)=>`<button class="tab ${state.tab===tab?'active':''}" data-tab="${tab}">${[kind==='ap'?t('Invoice overview','Resumen de facturas'):t('Journal summary','Resumen de póliza'),t('Transformed rows','Filas transformadas'),t('R365 columns','Columnas R365')][i]}</button>`).join('')}</div><div class="toolbar"><label class="search">${icon('search',14)}<input id="table-search" value="${esc(state.query)}" placeholder="${t('Search records…','Buscar registros…')}" aria-label="${t('Search records','Buscar registros')}"></label><small>${t('Mapping','Correspondencia')} v${b.mappingVersion} · ${t('revision','revisión')} ${b.revision}</small></div><div id="records-region">${records()}</div></section><aside class="workspace-sidebar">${controls(b)}${approval(b)}</aside></div><section class="panel" style="margin-top:20px"><div class="panel-heading"><h2>${t('Applied mapping','Correspondencia aplicada')}</h2></div><div class="panel-body"><div class="button-row"><select id="reprocess-mapping" class="select" aria-label="${t('Choose mapping','Elegir correspondencia')}">${state.workspace.mappings.items.filter(m=>m.kind===kind).map(m=>`<option value="${m.id}" ${m.id===b.mappingId?'selected':''}>${esc(m.name)} · v${m.version}</option>`).join('')}</select>${btn(t('Apply latest version','Aplicar última versión'),'reprocess','','sync',U.permissions.prepare?'':'disabled')}${U.permissions.manageUsers?btn(t('Configure from this source','Configurar con este archivo'),'new-mapping','','mapping'):''}</div><p class="small-note">${t('Reprocessing is recorded and invalidates the previous validation, review and approval. The original file remains unchanged.','El reproceso queda registrado e invalida la validación, revisión y aprobación previas. El archivo original se conserva.')}</p><p class="source-label">SHA-256: ${b.sourceHash}</p></div></section>`}${r365Notice()}`;}
  function controls(b){const s=b.summary;return `<section class="panel"><div class="panel-heading"><h2>${t('Server controls','Controles del servidor')}</h2>${icon('shield')}</div><div class="panel-body"><div class="balance-box">${b.kind==='ap'?`<div class="balance-row"><span>${t('Invoice totals','Totales de facturas')}</span><b>${money(s.total)}</b></div><div class="balance-row"><span>${t('Invoices','Facturas')}</span><b>${s.count||0}</b></div>`:`<div class="balance-row"><span>${t('Debits','Débitos')}</span><b>${money(s.debit)}</b></div><div class="balance-row"><span>${t('Credits','Créditos')}</span><b>${money(s.credit)}</b></div>`}<div class="balance-row"><span>${t('Blocking issues','Problemas bloqueantes')}</span><b>${s.issues.filter(i=>i.level==='error').length}</b></div></div>${s.issues.length?`<div class="control-list">${s.issues.slice(0,100).map(i=>`<div class="check-item ${i.level==='error'?'error':'review'}">${icon('alert',14)}<div><strong>${esc(issueName(i.code))}</strong><small>${i.field?esc(i.field)+' · ':''}${i.row?t('source row ','fila original ')+i.row:''}${i.number?esc(i.number):''}${i.batches?esc(i.batches.join(', ')):''}</small></div></div>`).join('')}</div>${s.issues.length>100?`<p class="small-note">${s.issues.length} ${t('issues in total.','problemas en total.')}</p>`:''}`:`<div class="check-item">${icon('check',14)}<strong>${t('All totals reconcile independently.','Todos los totales concilian de forma independiente.')}</strong></div>`}${btn(t('Validate batch','Validar lote'),'validate','full','shield',U.permissions.review?'':'disabled')}${s.issues.some(i=>i.level==='review')?`<div style="margin-top:10px">${btn(t('Record the review','Registrar revisión'),'review','full','alert',U.permissions.review?'':'disabled')}</div>`:''}${b.review?`<p class="small-note">${t('Reviewed by','Revisado por')} ${esc(b.review.by)}<br>${esc(b.review.note)}</p>`:''}</div></section>`;}
  function approval(b){return `<section class="panel"><div class="panel-heading"><h2>${t('Approval & export','Aprobación y exportación')}</h2></div><div class="panel-body">${b.approval?`<div class="info-strip">${t('Approved by','Aprobado por')} ${esc(b.approval.by)}</div>${btn(t('Download R365 CSV','Descargar CSV R365'),'export','primary full','download',U.permissions.export?'':'disabled')}`:`<p class="notice">${t('Validate the controls and record any review checkpoints before approval.','Valida los controles y registra los puntos de revisión antes de aprobar.')}</p>${btn(t('Approve batch','Aprobar lote'),'approve','primary full','check',U.permissions.approve&&b.status==='validated'?'':'disabled')}`}<p class="small-note">${t('Generating a CSV does not confirm an import into R365.','Generar un CSV no confirma su importación en R365.')}</p>${btn(t('Send to R365 TEST','Enviar a R365 TEST'),'send','full','link','disabled')}</div></section>`;}
  function records(){const b=state.batch;if(!b)return '';let rows=b.rows,cols=C[b.kind==='ap'?'AP_HEADERS':'JE_HEADERS'];
    if(state.tab==='invoices'&&b.kind==='ap'){rows=b.summary.groups||[];cols=['number','vendor','date','location','amount','detail'];}
    else if(state.tab==='invoices')cols=['JENumber','Date','Account','Debit','Credit','DetailLocation','DetailComment'];
    const filtered=rows.filter(r=>!state.query||JSON.stringify(r).toLowerCase().includes(state.query.toLowerCase())),pages=Math.max(1,Math.ceil(filtered.length/12));state.page=Math.min(state.page,pages-1);const start=state.page*12;
    return `<div class="table-wrap"><table class="data-table"><thead><tr>${cols.map(c=>`<th>${esc(c)}</th>`).join('')}${state.tab==='invoices'&&b.kind==='ap'?'<th></th>':''}</tr></thead><tbody>${filtered.slice(start,start+12).map(r=>`<tr>${cols.map(c=>`<td>${['amount','detail'].includes(c)?money(r[c]):esc(r[c])}</td>`).join('')}${state.tab==='invoices'&&b.kind==='ap'?`<td><button class="icon-btn" data-action="detail" data-key="${esc(r.key)}" aria-label="${t('Open invoice','Abrir factura')} ${esc(r.number)}">${icon('chevron',14)}</button></td>`:''}</tr>`).join('')||`<tr><td colspan="${cols.length}" class="empty">${t('No matching records.','No hay registros que coincidan.')}</td></tr>`}</tbody></table></div><div class="table-foot"><span>${filtered.length?start+1:0}–${Math.min(start+12,filtered.length)} ${t('of','de')} ${filtered.length}</span><div class="pager"><button data-action="prev" ${state.page?'':'disabled'} aria-label="${t('Previous page','Página anterior')}">‹</button><span>${state.page+1} / ${pages}</span><button data-action="next" ${state.page+1<pages?'':'disabled'} aria-label="${t('Next page','Página siguiente')}">›</button></div></div>`;
  }
  function mapping(){return `${head(labels.mapping(),t('Saved source-to-R365 mappings, reused on every upload of the same report type.','Correspondencias de origen a R365 guardadas y reutilizadas en cada carga del mismo tipo de reporte.'),U.permissions.manageUsers?btn(t('Add a report type','Agregar tipo de reporte'),'new-mapping','primary','plus'):'')}<div class="info-strip">${icon('info',16)}${t('The two initial mappings accept already-prepared R365 columns. A raw GlobalBake report needs its own field mapping based on a complete source CSV; no store or account conversion is assumed.','Las dos correspondencias iniciales aceptan columnas R365 ya preparadas. Un reporte GlobalBake original necesita su correspondencia basada en un CSV completo; no se supone conversión de tienda ni de cuenta.')}</div><div class="user-grid">${state.workspace.mappings.items.map(m=>`<section class="user-card"><h3>${esc(m.name)}</h3><p style="margin-top:12px">${m.kind.toUpperCase()} · ${t('Current version','Versión actual')} ${m.version}</p>${btn(t('View versions and fields','Ver versiones y campos'),'edit-mapping','','mapping',`data-id="${m.id}"`)}</section>`).join('')}</div>`;}
  function activity(){return `${head(labels.activity(),t('Persistent records of uploads, mapping changes, reviews, approvals and generated files.','Registro persistente de cargas, cambios de correspondencia, revisiones, aprobaciones y archivos generados.'),btn(t('Refresh','Actualizar'),'refresh','','sync'))}<section class="panel">${state.workspace.events.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>${t('Time','Fecha')}</th><th>${t('User','Usuario')}</th><th>${t('Action','Acción')}</th><th>${t('Details','Detalles')}</th></tr></thead><tbody>${state.workspace.events.map(e=>`<tr><td>${esc(e.at)}</td><td>${esc(e.actor)}</td><td class="row-title">${esc(e.action)}</td><td class="audit-details">${esc(JSON.stringify(e.detail))}</td></tr>`).join('')}</tbody></table></div>`:empty(t('No recorded action yet','Todavía no hay acciones registradas'),t('The first source-file upload will appear here.','La primera carga de un archivo aparecerá aquí.'))}</section><p class="small-note">${t('Latest 1,000 audit events are listed. Older records remain stored.','Se muestran los últimos 1.000 eventos. Los anteriores permanecen almacenados.')}</p>`;}
  function team(){return `${head(labels.team(),t('Individual accounts and server-assigned permissions.','Cuentas individuales y permisos asignados en el servidor.'))}<div class="user-grid">${TEAM.map(u=>`<section class="user-card"><div class="user-card-head">${avatar(u)}<div><h3>${esc(u.name)}</h3><span class="email">${esc(u.email)}</span></div></div><div class="user-card-footer">${pill(role(u.role))}${pill(t('Active account','Cuenta activa'),'outline')}</div></section>`).join('')}</div>`;}
  function r365Notice(){return `<div class="info-strip" style="margin-top:20px">${icon('link',16)}<div><strong>${t('R365 TEST connection pending','Conexión R365 TEST pendiente')}</strong><br>${t('The test instance, credentials and documented AP/JE write operations are required before any transmission. No file is sent automatically.','Se requieren instancia de prueba, credenciales y operaciones de escritura AP/JE documentadas antes de transmitir. Ningún archivo se envía automáticamente.')}</div></div>`;}
  function r365(){return `${head(labels.r365(),t('A separate, explicit test submission after review and approval.','Un envío de prueba separado y explícito después de revisión y aprobación.'))}${r365Notice()}<section class="panel"><div class="panel-heading"><h2>${t('Required from the R365 team','Requerido del equipo R365')}</h2>${pill(t('Not configured','Sin configurar'),'amber')}</div><div class="panel-body"><p class="notice">${t('Test instance URL; authentication method and credentials; authorized invoice and journal write endpoints; payload specification; acceptance, rejection and import-confirmation responses.','URL de instancia de prueba; método y credenciales de autenticación; endpoints de escritura autorizados para facturas y pólizas; formato de datos; respuestas de aceptación, rechazo y confirmación de importación.')}</p>${btn(t('Send to R365 TEST','Enviar a R365 TEST'),'send','primary','link','disabled')}<p class="small-note">${t('No production accounting connection is configured. Downloaded files have not been imported into R365.','No hay conexión contable de producción configurada. Los archivos descargados no se han importado en R365.')}</p></div></section>`;}
  function guide(){const steps=[t('Rosa or Jorge generates the report in GlobalBake and obtains the CSV. Confirm the supported export method and options with Pam for each report.','Rosa o Jorge genera el reporte en GlobalBake y obtiene el CSV. Confirma con Pam el método y las opciones de exportación de cada reporte.'),t('Choose the report type and period, then upload the source CSV. The original bytes, SHA-256, uploader and period are retained.','Elige tipo y período y carga el CSV original. Se conservan los bytes originales, SHA-256, autor y período.'),t('The server applies the saved mapping version and runs the accounting controls. Unknown columns or codes block the batch with diagnostics.','El servidor aplica la versión de correspondencia guardada y los controles contables. Columnas o códigos desconocidos bloquean el lote con diagnósticos.'),t('Review negative entries, period comments, multiple locations and possible duplicate documents. Record your decision without silently changing the source.','Revisa negativos, comentarios de período, ubicaciones y posibles duplicados. Registra la decisión sin modificar silenciosamente el original.'),t('Validate, obtain approval from an authorized account and generate the R365 CSV. The file and decision are recorded in the audit log.','Valida, obtén aprobación de una cuenta autorizada y genera el CSV R365. El archivo y la decisión quedan registrados.'),t('When the R365 TEST contract and access are configured, a separate authorized action will submit the batch and retain the actual response. This step is currently blocked.','Cuando estén configurados el contrato y acceso a R365 TEST, una acción autorizada separada enviará el lote y guardará la respuesta real. Esta etapa está bloqueada actualmente.')];return `${head(labels.guide(),t('The operational process and the external dependencies that remain.','El proceso operativo y las dependencias externas pendientes.'))}<section class="panel"><div class="panel-body">${steps.map((s,i)=>`<div class="guide-step"><span class="guide-number">${i+1}</span><div><p>${s}</p></div></div>`).join('')}</div></section>`;}
  function dialog(title,body,footer=''){el('modal').innerHTML=`<div class="dialog-head"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close" aria-label="${t('Close','Cerrar')}">${icon('close')}</button></div><div class="dialog-body">${body}</div>${footer?`<div class="dialog-footer">${footer}</div>`:''}`;if(!el('modal').open)el('modal').showModal();}
  function openImport(kind=state.view==='sales'?'sales':'ap'){
    dialog(t('Upload a source CSV','Cargar un CSV original'),`<p class="notice">${t('The source file will be stored privately on the server with your account and the selected period. UTF-8 CSV, up to 2 MB.','El archivo original se guardará de forma privada en el servidor con tu cuenta y período. CSV UTF-8, hasta 2 MB.')}</p><label class="form-field">${t('Report type / saved mapping','Tipo de reporte / correspondencia guardada')}<select id="upload-mapping">${state.workspace.mappings.items.map(m=>`<option value="${m.id}" ${m.kind===kind&&m.id===kind+'-r365'?'selected':''}>${esc(m.name)}</option>`).join('')}</select></label><div class="form-row"><label class="form-field">${t('Period start','Inicio de período')}<input id="period-from" type="date" required></label><label class="form-field">${t('Period end','Fin de período')}<input id="period-to" type="date" required></label></div><label class="form-field">${t('Source CSV','CSV original')}<input id="source-file" type="file" accept=".csv,text/csv"></label><div id="dialog-error"></div><p class="small-note">${t('If the file uses raw GlobalBake columns, an administrator can configure a report type from the blocked source after upload. Do not rename an XLSX or AP0001 file to CSV.','Si el archivo usa columnas originales de GlobalBake, un administrador puede configurar su correspondencia desde el lote bloqueado. No cambies la extensión de XLSX o AP0001 a CSV.')}</p>`,btn(t('Cancel','Cancelar'),'close')+btn(t('Upload & run controls','Cargar y ejecutar controles'),'upload','primary','upload'));
  }
  let editingMapping=null;
  async function mappingDialog(id){
    const existing=id?await json('mappings/'+id):null;editingMapping=existing;
    const kind=existing?.kind||state.batch?.kind||'ap',v=existing?.versions.at(-1),source=state.batch?.sourceHeaders||[],fields=C[kind==='ap'?'AP_HEADERS':'JE_HEADERS'];
    dialog(t('Report mapping','Correspondencia del reporte'),`<p class="notice">${t('Each save creates a new version. Existing batches are reprocessed only by an explicit action.','Cada guardado crea una versión. Los lotes existentes se reprocesan sólo con una acción explícita.')}</p><div class="form-row"><label class="form-field">${t('Report name','Nombre del reporte')}<input id="mapping-name" value="${esc(existing?.name||'')}"></label><label class="form-field">${t('R365 target','Destino R365')}<select id="mapping-kind" ${existing||state.batch?'disabled':''}><option value="ap" ${kind==='ap'?'selected':''}>Vendor Transaction by Account</option><option value="sales" ${kind==='sales'?'selected':''}>Journal Entry</option></select></label></div><p class="small-note">${t('Source headers available','Encabezados originales disponibles')}: ${esc(source.join(', ')||t('Type exact CSV header names below.','Escribe los nombres exactos de encabezado CSV abajo.'))}</p><div id="mapping-fields">${mappingFields(fields,v?.fields||Object.fromEntries(fields.map(h=>[h,{column:source.includes(h)||!source.length?h:'',constant:''}])))}</div><details><summary>${t('Filter, code lookups and grouping','Filtro, correspondencias de códigos y agrupación')}</summary><label class="form-field">${t('Filter source column','Columna original para filtrar')}<input id="filter-column" value="${esc(v?.filter?.column||'')}"></label><label class="form-field">${t('Keep rows equal to','Conservar filas iguales a')}<input id="filter-equals" value="${esc(v?.filter?.equals||'')}"></label><label class="form-field">${t('Code lookups JSON — target field → source code → approved code','Correspondencias JSON — campo destino → código original → código validado')}<textarea id="mapping-lookups">${esc(JSON.stringify(v?.lookups||{},null,2))}</textarea></label><label class="form-field">${t('Group by target fields, comma separated (optional)','Agrupar por campos destino, separados por coma (opcional)')}<input id="mapping-groups" value="${esc((v?.groupBy||[]).join(', '))}"><small>${t('Only detail amounts (AP) or debits/credits (JE) are added. Conflicting other values block grouping.','Sólo se suman importes de detalle (AP) o débitos/créditos (JE). Otros valores en conflicto bloquean la agrupación.')}</small></label></details><label class="form-field">${t('Version note','Nota de versión')}<textarea id="mapping-note"></textarea></label>${existing?`<p class="small-note">${t('Versions','Versiones')}: ${existing.versions.map(v=>`v${v.version} · ${esc(v.by)} · ${esc(v.at)}`).join('<br>')}</p>`:''}<div id="dialog-error"></div>`,btn(t('Close','Cerrar'),'close')+(U.permissions.manageUsers?btn(t('Save mapping version','Guardar versión'),'save-mapping','primary','check'):''));
  }
  function mappingFields(fields,values){return `<div class="mapping-table"><div class="mapping-row mapping-heading"><span>${t('R365 field','Campo R365')}</span><span>${t('CSV source column','Columna CSV original')}</span><span>${t('Constant (if no column)','Constante (sin columna)')}</span><span>${t('Transformation','Transformación')}</span></div>${fields.map(h=>{const f=values[h]||{};return `<div class="mapping-row" data-target="${h}"><label>${h}</label><input data-map-column value="${esc(f.column||'')}" aria-label="${esc(h)} source"><input data-map-constant value="${esc(f.constant??'')}" aria-label="${esc(h)} constant"><select data-map-transform aria-label="${esc(h)} transform">${['identity','account0092','isoDate','cents'].map(k=>`<option ${k===(f.transform||'identity')?'selected':''}>${k}</option>`).join('')}</select></div>`;}).join('')}</div>`;}
  async function downloadResponse(response){const blob=await response.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=response.headers.get('Content-Disposition')?.match(/filename="([^"]+)"/)?.[1]||'GBtoR365.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
  async function act(action,target){
    if(action==='close'){el('modal').close();return;}
    if(action==='menu'){document.querySelector('.sidebar').classList.toggle('open');document.querySelector('.mobile-scrim').classList.toggle('open');return;}
    if(action==='language'){state.lang=state.lang==='en'?'es':'en';try{localStorage.setItem('gbtor365-language',state.lang);}catch{}render();return;}
    if(action==='profile'){dialog(t('Your account','Tu cuenta'),`<p class="notice">${esc(U.name)}<br>${esc(U.email)}<br>${role(U.role)}</p>`,btn(t('Close','Cerrar'),'close')+btn(t('Sign out','Cerrar sesión'),'logout','primary'));return;}
    if(action==='logout'){await api('logout',{});location.replace('/login');return;}
    if(action==='refresh'){await refresh();if(state.batch)state.batch=await json('batches/'+state.batch.id);render();return;}
    if(action==='open-batch'){await nav(target.dataset.kind);await selectBatch(target.dataset.id);return;}
    if(action==='import'){if(!U.permissions.prepare)return;openImport(target.dataset.kind);return;}
    if(action==='prev'||action==='next'){state.page+=action==='next'?1:-1;el('records-region').innerHTML=records();return;}
    if(action==='upload'){
      const file=el('source-file').files[0];if(!file)throw Error(t('Choose a CSV file.','Elige un CSV.'));if(file.size>2*1024*1024)throw Error(errorText('file_limit'));
      const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));
      const result=await json('batches',{name:file.name,contentBase64:btoa(binary),mappingId:el('upload-mapping').value,period:{from:el('period-from').value,to:el('period-to').value}});
      el('modal').close();await refresh();state.batch=result.batch;state.view=result.batch.kind;history.replaceState(null,'','#'+state.view);state.tab='invoices';state.page=0;state.query='';render();toast(result.duplicate?t('This source file is already stored. The existing batch was opened.','Este archivo ya está guardado. Se abrió el lote existente.'):t('Original file stored. Server controls completed.','Archivo original guardado. Controles del servidor completados.'));return;
    }
    if(action==='detail'){const b=state.batch,g=b.summary.groups.find(g=>g.key===target.dataset.key),rows=b.rows.filter(r=>JSON.stringify([r.Location,r.Vendor,r.Number])===g.key);dialog(t('Invoice ','Factura ')+esc(g.number),`<div class="detail-summary"><div><small>${t('Vendor','Proveedor')}</small><strong>${esc(g.vendor)}</strong></div><div><small>${t('Invoice total','Total factura')}</small><strong>${money(g.amount)}</strong></div><div><small>${t('Allocation total','Total detalle')}</small><strong>${money(g.detail)}</strong></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Account</th><th>Amount</th><th>Location</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r['Detail Account'])}</td><td>${esc(r['Detail Amount'])}</td><td>${esc(r['Detail Location'])}</td></tr>`).join('')}</tbody></table></div>`,btn(t('Close','Cerrar'),'close'));return;}
    if(action==='review'){
      const codes=[...new Set(state.batch.summary.issues.filter(i=>i.level==='review').map(i=>i.code))];dialog(t('Record source review','Registrar revisión del origen'),`<p class="notice">${t('The original amounts, signs and comments will remain unchanged. Record the decision for every checkpoint.','Los importes, signos y comentarios originales no se modificarán. Registra la decisión para cada punto.')}</p>${codes.map(c=>`<label class="approval-box"><input type="checkbox" data-review-code="${c}">${esc(issueName(c))}</label>`).join('')}<label class="form-field">${t('Review decision / explanation','Decisión / explicación de la revisión')}<textarea id="review-note" maxlength="2000" required>${esc(state.batch.review?.note||'')}</textarea></label><div id="dialog-error"></div>`,btn(t('Cancel','Cancelar'),'close')+btn(t('Save review','Guardar revisión'),'save-review','primary'));return;
    }
    if(action==='approve'){dialog(t('Approve this batch','Aprobar este lote'),`<p class="notice">${t('Your name and decision will be recorded. This authorizes CSV generation, not transmission to R365.','Se registrarán tu nombre y decisión. Autoriza generar el CSV, no enviarlo a R365.')}</p><label class="approval-box"><input id="approval-confirm" type="checkbox">${t('I have reviewed the source, controls and review notes.','He revisado el origen, controles y notas de revisión.')}</label><div id="dialog-error"></div>`,btn(t('Cancel','Cancelar'),'close')+btn(t('Confirm approval','Confirmar aprobación'),'confirm-approve','primary'));return;}
    if(['validate','save-review','confirm-approve','reprocess','export'].includes(action)){
      if(action==='confirm-approve'&&!el('approval-confirm').checked)throw Error(t('Confirm that you reviewed the batch.','Confirma la revisión del lote.'));
      const b=state.batch,body={version:b.version};let name=action==='save-review'?'review':action==='confirm-approve'?'approve':action;
      if(action==='save-review'){body.codes=[...el('modal').querySelectorAll('[data-review-code]:checked')].map(n=>n.dataset.reviewCode);body.note=el('review-note').value;}
      if(action==='reprocess'){if(!confirm(t('Reprocess and invalidate this batch’s previous decisions?','¿Reprocesar e invalidar las decisiones anteriores del lote?')))return;body.mappingId=el('reprocess-mapping').value;}
      const response=await api('batches/'+b.id+'/'+name,body);if(action==='export')await downloadResponse(response);else state.batch=await response.json();
      el('modal').close();await refresh();state.batch=await json('batches/'+b.id);render();toast(t('Action recorded on the server.','Acción registrada en el servidor.'));return;
    }
    if(action==='new-mapping'||action==='edit-mapping'){await mappingDialog(target.dataset.id);return;}
    if(action==='save-mapping'){
      const fields=Object.fromEntries([...el('mapping-fields').querySelectorAll('[data-target]')].map(row=>[row.dataset.target,{column:row.querySelector('[data-map-column]').value.trim(),constant:row.querySelector('[data-map-constant]').value,transform:row.querySelector('[data-map-transform]').value}]));
      let lookups;try{lookups=JSON.parse(el('mapping-lookups').value);}catch{throw Error(t('Code lookups must be valid JSON.','Las correspondencias de códigos deben ser JSON válido.'));}
      const body={id:editingMapping?.id,version:editingMapping?.version,name:el('mapping-name').value,kind:el('mapping-kind').value,fields,filter:el('filter-column').value?{column:el('filter-column').value,equals:el('filter-equals').value}:null,lookups,groupBy:el('mapping-groups').value.split(',').map(s=>s.trim()).filter(Boolean),note:el('mapping-note').value,sourceBatchId:state.batch?.kind===el('mapping-kind').value?state.batch.id:undefined};
      const mapping=await json('mappings',body);el('modal').close();await refresh();render();toast(t('Mapping version saved. Apply it explicitly to reprocess an existing batch.','Versión guardada. Aplícala explícitamente para reprocesar un lote existente.'));return;
    }
  }
  document.addEventListener('click',async event=>{const navTarget=event.target.closest('[data-nav]'),tab=event.target.closest('[data-tab]'),target=event.target.closest('[data-action]');if(!navTarget&&!tab&&!target)return;event.preventDefault();if(target?.disabled||state.busy)return;
    try{state.busy=true;document.body.dataset.busy='true';if(navTarget)await nav(navTarget.dataset.nav);else if(tab){state.tab=tab.dataset.tab;state.page=0;render();}else{target.disabled=true;await act(target.dataset.action,target);}}
    catch(error){if(el('modal').open&&el('dialog-error'))el('dialog-error').innerHTML=`<div class="error-box">${esc(error.message)}</div>`;else toast(error.message);}
    finally{state.busy=false;delete document.body.dataset.busy;if(target?.isConnected)target.disabled=false;}
  });
  document.addEventListener('input',e=>{if(e.target.id==='table-search'){state.query=e.target.value;state.page=0;el('records-region').innerHTML=records();}});
  document.addEventListener('change',async e=>{try{if(e.target.id==='batch-select')await selectBatch(e.target.value);if(e.target.id==='mapping-kind')el('mapping-fields').innerHTML=mappingFields(C[e.target.value==='ap'?'AP_HEADERS':'JE_HEADERS'],{});}catch(error){toast(error.message);}});
  window.addEventListener('hashchange',()=>{const view=location.hash.slice(1);if(labels[view]&&view!==state.view)nav(view).catch(e=>toast(e.message));});
  (async()=>{try{await refresh();await nav(labels[location.hash.slice(1)]?location.hash.slice(1):'overview');}catch(error){el('app').innerHTML=`<main class="content"><h1>GBtoR365</h1><div class="error-box">${esc(error.message)}</div><button class="btn" data-action="refresh">${t('Retry','Reintentar')}</button></main>`;}})();
})();
